  lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityStopped(Activity a){if(a==activity&&!closed){suspended=true;revision++;syncRevision++;reading=false;invalidateContent("返回后将重新核对账号…");for(AgentUI.Screen screen:new ArrayList<>(syncScreens))if(screen.dialog.isShowing()){screen.body.removeAllViews();screen.body.addView(AgentUI.text(activity,"返回后将重新核对资料连接…",14,AgentUI.MUTED));}}}public void onActivityResumed(Activity a){if(a==activity&&!closed&&suspended){suspended=false;if(browsing&&active&&syncScreens.isEmpty())refresh();for(AgentUI.Screen screen:new ArrayList<>(syncScreens))if(screen.dialog.isShowing())reloadSync(screen);}}public void onActivityDestroyed(Activity a){if(a==activity)close();}public void onActivityCreated(Activity a,android.os.Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivitySaveInstanceState(Activity a,android.os.Bundle b){}};
