  titles.addView(MaterialReadingUI.bold(AgentUI.text(a,(selected.equals(LocalDate.now(zone))?"今天 · ":"")+selected.getMonthValue()+"月"+selected.getDayOfMonth()+"日 周"+weekdayName+" · "+entries.size()+" 条",17,AgentUI.INK)));AgentUI.gap(a,titles,4);titles.addView(MaterialReadingUI.line(a,dayStatus(entries.size()),12,AgentUI.MUTED,2));header.addView(titles,new LinearLayout.LayoutParams(0,-2,1));
  LinearLayout order=new LinearLayout(a);order.setGravity(Gravity.CENTER_VERTICAL);order.setPadding(AgentUI.dp(a,10),0,AgentUI.dp(a,10),0);order.setBackground(MaterialReadingUI.outline(a,10));MaterialReadingUI.glyph(a,order,"sort",AgentUI.INK,14);order.addView(AgentUI.text(a," "+(newestFirst?"最新在前":"最早在前"),12,AgentUI.INK));order.setFocusable(true);order.setContentDescription("排序："+(newestFirst?"最新在前":"最早在前"));order.setOnClickListener(v->{newestFirst=!newestFirst;render();});LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(-2,AgentUI.dp(a,36));op.leftMargin=AgentUI.dp(a,8);header.addView(order,op);
